create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text not null,role text not null default 'user' check(role in ('user','admin','moderator')),status text not null default 'active' check(status in ('active','suspended','banned')),created_at timestamptz default now());
create table if not exists profiles(user_id uuid primary key references users(id) on delete cascade,public_id bigint unique not null,username text unique not null,display_name text not null,avatar_url text,country text,gender text,birth_date date,bio text,level int default 1,vip_level int default 0,experience bigint default 0,created_at timestamptz default now());
create table if not exists rooms(id uuid primary key default gen_random_uuid(),owner_id uuid not null references users(id),name text not null,description text default '',cover_url text,country text default 'EG',language text default 'ar',category text default 'general',is_private boolean default false,max_seats int default 8 check(max_seats between 1 and 15),announcement text,rules text,status text default 'live' check(status in ('live','ended','blocked')),viewer_count int default 0,created_at timestamptz default now());
create table if not exists room_members(room_id uuid references rooms(id) on delete cascade,user_id uuid references users(id) on delete cascade,joined_at timestamptz default now(),primary key(room_id,user_id));
create table if not exists room_seats(room_id uuid references rooms(id) on delete cascade,seat_no int not null, user_id uuid references users(id) on delete set null,muted boolean default false,locked boolean default false,updated_at timestamptz default now(),primary key(room_id,seat_no),check(seat_no between 1 and 15));
create table if not exists room_moderators(room_id uuid references rooms(id) on delete cascade,user_id uuid references users(id) on delete cascade,permissions jsonb not null default '{}'::jsonb,created_at timestamptz default now(),primary key(room_id,user_id));
create table if not exists room_bans(room_id uuid references rooms(id) on delete cascade,user_id uuid references users(id) on delete cascade,reason text,expires_at timestamptz,created_at timestamptz default now(),primary key(room_id,user_id));
create table if not exists room_messages(id uuid primary key default gen_random_uuid(),room_id uuid references rooms(id) on delete cascade,user_id uuid references users(id),text text not null,created_at timestamptz default now());
create index if not exists room_messages_room_created on room_messages(room_id,created_at desc);
create table if not exists wallet_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id),currency text not null check(currency in ('coins','diamonds')),amount bigint not null,type text not null,reference_id text unique not null,metadata jsonb,created_at timestamptz default now());
create table if not exists gifts(id uuid primary key default gen_random_uuid(),name text not null,price bigint not null,currency text not null default 'coins',asset_url text,animation_url text,sound_url text,duration_ms int default 2500,required_level int default 1,active boolean default true);
insert into gifts(name,price,currency) select 'وردة',10,'coins' where not exists(select 1 from gifts where name='وردة');
insert into gifts(name,price,currency) select 'قلب',20,'coins' where not exists(select 1 from gifts where name='قلب');
insert into gifts(name,price,currency) select 'سيارة',100,'coins' where not exists(select 1 from gifts where name='سيارة');
insert into gifts(name,price,currency) select 'طائرة',200,'coins' where not exists(select 1 from gifts where name='طائرة');
insert into gifts(name,price,currency) select 'قصر',1000,'coins' where not exists(select 1 from gifts where name='قصر');
create table if not exists gift_transactions(id uuid primary key default gen_random_uuid(),sender_id uuid not null references users(id),receiver_id uuid references users(id),room_id uuid references rooms(id),gift_id uuid not null references gifts(id),quantity int not null check(quantity>0),unit_price bigint not null,total_price bigint not null,idempotency_key text unique not null,created_at timestamptz default now());
create table if not exists reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references users(id),target_user_id uuid references users(id),room_id uuid references rooms(id),message_id uuid references room_messages(id),reason text not null,status text default 'pending',reviewer_id uuid references users(id),reviewer_note text,created_at timestamptz default now(),reviewed_at timestamptz);
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references users(id),action text not null,target_type text,target_id text,payload jsonb,created_at timestamptz default now());
